changeSet.sql:
-- ---- search_topic_set_384 CREATE FUNCTION nexus.search_topic_set_384(p_query nexus.vector, p_topic_ids bigint[], p_collection text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c WHERE COALESCE(cardinality(p_topic_ids), 0) > 0 AND c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND c.embedding_384 IS NOT NULL AND EXISTS ( SELECT 1 FROM nexus.topic_assignments ta JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash AND t.collection = p_collection AND ta.topic_id = ANY(p_topic_ids)) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE p_exclude_sensitive IS NOT FALSE AND sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.collection = p_collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $function$;
REVOKE EXECUTE ON FUNCTION nexus.search_topic_set_384(nexus.vector,bigint[],text,integer,text,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.search_topic_set_384(nexus.vector,bigint[],text,integer,text,text,boolean) TO nexus_svc;
