REVOKE EXECUTE ON FUNCTION nexus.search_topic_set_768(nexus.vector,bigint[],text,integer,text,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.search_topic_set_768(nexus.vector,bigint[],text,integer,text,text,boolean) TO nexus_svc;
