REVOKE EXECUTE ON FUNCTION nexus.search_topic_set_1024(nexus.vector,bigint[],text,integer,text,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.search_topic_set_1024(nexus.vector,bigint[],text,integer,text,text,boolean) TO nexus_svc;

rollback.sql:
DROP FUNCTION IF EXISTS nexus.search_topic_set_384(nexus.vector,bigint[],text,integer,text,text,boolean);
DROP FUNCTION IF EXISTS nexus.search_topic_set_768(nexus.vector,bigint[],text,integer,text,text,boolean);
DROP FUNCTION IF EXISTS nexus.search_topic_set_1024(nexus.vector,bigint[],text,integer,text,text,boolean);
